practiceBank.solution:
using System;
var data = Console.In.ReadToEnd().Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries); int a = int.Parse(data[0]), b = int.Parse(data[1]);
while (b != 0) { int r = a % b; a = b; b = r; } int answer = a;
Console.WriteLine(answer);

practiceBank.starter:
using System;
int n = int.Parse(Console.ReadLine()!);
// Напиши решение

practiceBank.solution:
using System;
int n = int.Parse(Console.ReadLine()!);
int answer = 0; for (int i = 1; i <= n; i++) if (i % 3 == 0) answer += i;
Console.WriteLine(answer);

